CREATE OR REPLACE FUNCTION public.support_ai_fallback(p_id uuid,p_error text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.support_auto_suggestions%ROWTYPE; BEGIN SELECT * INTO s FROM public.support_auto_suggestions WHERE id=p_id FOR UPDATE; IF NOT FOUND OR s.status<>'processando' THEN RETURN NULL; END IF; UPDATE public.support_auto_suggestions SET ai_status='falhou_reserva',ai_error=left(p_error,500),status=CASE WHEN public.support_cost_keywords(incoming_text) THEN 'nova' ELSE 'ignorada' END,decision='fila',reason='reserva_palavras:'||left(p_error,200),suggested_text=NULL,handoff_summary='Reserva sem IA: revisar o pedido de suporte da cliente; nenhum envio ou movimento realizado.',would_route_support=public.support_cost_keywords(incoming_text),auto_send_after=NULL,link_type=NULL WHERE id=p_id; RETURN p_id; END $$; REVOKE ALL ON FUNCTION public.support_ai_fallback(uuid,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.support_ai_fallback(uuid,text) TO service_role;